package app

// Was ein Werkzeug auf den anderen Flächen heißt — Werkstück U12 von
// Phase 5.1 (#1423).
//
// Abgeschrieben aus `docs/FAEHIGKEITEN.md`, Zeile für Zeile: je MCP-Werkzeug
// die Fähigkeit, die es einlöst, ihr Befehl auf der Kommandozeile und ihr Weg
// im Dienst. Die Tabelle dort ist die Quelle — sie hält die Wächter gegen
// den Quelltext —, und `befehlsverweise_test.go` hält diese Abschrift gegen
// die Tabelle: eine Zeile, die dort anders steht, macht den Test rot.
//
// Warum abgeschrieben und nicht gelesen: die Anwendung trägt ihre
// Dokumentation nicht im Bündel, und eine Auskunft, die eine Datei neben dem
// Programm braucht, hätte am falschen Rechner keine.

// Befehlsverweis ist die Fähigkeit hinter einem Werkzeug samt ihren Namen auf
// Kommandozeile und Dienst — leer, wo eine Fläche sie nicht hat.
type Befehlsverweis struct {
	Faehigkeit string
	CLI        string
	REST       string
}

// Befehlsverweise sind alle, je Werkzeugname.
func Befehlsverweise() map[string]Befehlsverweis {
	kopie := make(map[string]Befehlsverweis, len(befehlsverweise))
	for name, verweis := range befehlsverweise {
		kopie[name] = verweis
	}

	return kopie
}

